using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Linq;

internal sealed class Updates {
 readonly object gate=new object();readonly Action<string> emit;readonly string dir;Dictionary<string,object> state=new Dictionary<string,object>(),payload;string envelope="";CancellationTokenSource cancellation;bool busy;long revision;string preferred="",custom="",highest=UpdateProtocol.Current;bool automatic=true;long checkedAt;
 string Settings{get{return Path.Combine(dir,"settings.json");}}string Package{get{return Path.Combine(dir,"package.zip");}}
 internal Updates(Action<string> onChange){emit=onChange;dir=Path.Combine(Program.DataDir,"updates");Directory.CreateDirectory(dir);try{var p=UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Settings));automatic=Convert.ToBoolean(p["automatic"]);custom=UpdateProtocol.Prefix(UpdateProtocol.Text(p,"custom"));preferred=UpdateProtocol.Text(p,"preferred");highest=UpdateProtocol.Text(p,"highest");UpdateProtocol.VersionOf(highest);checkedAt=Convert.ToInt64(p["checkedAt"]);}catch{highest=UpdateProtocol.Current;}state["phase"]="idle";state["message"]="更新检查使用镜像备用线路，不影响资料库操作。";try{string path=Path.Combine(dir,"manifest.json");if(File.Exists(path)&&File.Exists(Package)){envelope=File.ReadAllText(path);payload=UpdateProtocol.Verify(envelope,"windows");if(UpdateProtocol.VersionOf(UpdateProtocol.Text(payload,"version"))>UpdateProtocol.VersionOf(UpdateProtocol.Current)){UpdateProtocol.VerifyFile(Package,UpdateProtocol.Object(payload,"windows"));state["phase"]="ready";state["message"]="已校验的安装包可以安装。";}else payload=null;}}catch{payload=null;}
  string log=Path.Combine(dir,"install-result.json");if(File.Exists(log)){try{var p=UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(log));state["message"]=UpdateProtocol.Text(p,"message");}catch{}try{File.Delete(log);}catch{}}
 }
 void Persist(){File.WriteAllText(Settings,UpdateProtocol.Serializer().Serialize(new{automatic=automatic,custom=custom,preferred=preferred,highest=highest,checkedAt=checkedAt}));}
 string Snapshot(){lock(gate){state["revision"]=++revision;state["current"]=UpdateProtocol.Current;state["automatic"]=automatic;state["custom"]=custom;state["preferred"]=preferred;state["checkedAt"]=checkedAt;if(payload!=null){state["latest"]=payload["version"];state["notes"]=UpdateProtocol.Text(payload,"notes");}return UpdateProtocol.Serializer().Serialize(state);}}
 void Changed(string phase,string message){lock(gate){state["phase"]=phase;state["message"]=message;}emit(Snapshot());}
 bool Begin(){lock(gate){if(busy)return false;busy=true;cancellation=new CancellationTokenSource();return true;}}
 void End(){lock(gate){busy=false;}}
 string[] Routes(){var rows=new List<string>();if(custom!="")rows.Add(custom);if(preferred!="")rows.Add(preferred=="direct"?"":preferred);rows.AddRange(UpdateProtocol.Mirrors);return rows.Distinct().ToArray();}
 internal string Request(Dictionary<string,object> x){string action=UpdateProtocol.Text(x,"action");if(action=="settings"){lock(gate){bool nextAuto=Convert.ToBoolean(x["automatic"]);string nextCustom=UpdateProtocol.Prefix(UpdateProtocol.Text(x,"custom"));string p=UpdateProtocol.Text(x,"preferred");if(p!=""&&p!="direct"&&!UpdateProtocol.Mirrors.Contains(p))throw new Exception("未知更新线路");automatic=nextAuto;custom=nextCustom;preferred=p;Persist();}}else if(action=="check")Check(false);else if(action=="auto")Check(true);else if(action=="download")Download();else if(action=="cancel"){lock(gate){if(cancellation!=null)cancellation.Cancel();}}else if(action=="install")Install();else if(action!="state")throw new Exception("未知更新操作");return Snapshot();}
 void Check(bool auto){lock(gate){if(auto&&(!automatic||DateTimeOffset.UtcNow.ToUnixTimeSeconds()-checkedAt<21600))return;}bool wasReady=Convert.ToString(state["phase"])=="ready";if(!Begin())return;Changed("checking","正在检查版本，镜像线路并行响应…");var token=cancellation.Token;string[] routes=Routes();Task.Run(()=>{try{var rows=new List<Tuple<string,Dictionary<string,object>,string>>();object collected=new object();Parallel.ForEach(routes,route=>{try{string raw=UpdateProtocol.ReadText(route+UpdateProtocol.ManifestUrl+"?t="+(DateTimeOffset.UtcNow.ToUnixTimeSeconds()/3600),token);var p=UpdateProtocol.Verify(raw,"windows");lock(collected)rows.Add(Tuple.Create(raw,p,route));}catch{}});token.ThrowIfCancellationRequested();if(rows.Count==0)throw new Exception("所有更新线路暂时不可达，或签名校验失败。可稍后重试或更换镜像。");var best=rows.OrderByDescending(r=>UpdateProtocol.VersionOf(UpdateProtocol.Text(r.Item2,"version"))).First();string version=UpdateProtocol.Text(best.Item2,"version");if(UpdateProtocol.VersionOf(version)<UpdateProtocol.VersionOf(highest))throw new Exception("线路返回旧版本信息，已阻止回退，请换线路重试。");lock(gate){payload=best.Item2;envelope=best.Item1;highest=version;checkedAt=DateTimeOffset.UtcNow.ToUnixTimeSeconds();state["route"]=best.Item3==""?"GitHub 直连":new Uri(best.Item3).Host;Persist();}bool newer=UpdateProtocol.VersionOf(version)>UpdateProtocol.VersionOf(UpdateProtocol.Current),cached=false;if(newer&&File.Exists(Package))try{UpdateProtocol.VerifyFile(Package,UpdateProtocol.Object(payload,"windows"));File.WriteAllText(Path.Combine(dir,"manifest.json"),envelope);cached=true;}catch{}Changed(cached?"ready":newer?"available":"latest",cached?"安装包已下载并校验，可确认安装。":newer?"发现新版本，下载后由你确认安装。":"当前已是最新版本。");}catch(Exception e){Changed(wasReady?"ready":token.IsCancellationRequested?"idle":"error",token.IsCancellationRequested?"已取消检查。":e.Message);}finally{End();}});}
 void Download(){lock(gate){if(payload==null||UpdateProtocol.VersionOf(UpdateProtocol.Text(payload,"version"))<=UpdateProtocol.VersionOf(UpdateProtocol.Current))throw new Exception("请先检查新版本");if(Convert.ToString(state["phase"])=="ready")return;}if(!Begin())return;var token=cancellation.Token;var a=UpdateProtocol.Object(payload,"windows");long size=Convert.ToInt64(a["size"]);string raw=envelope;Changed("downloading","正在准备镜像下载…");Task.Run(()=>{string part=Package+".part";try{Exception last=null;foreach(string route in Routes()){token.ThrowIfCancellationRequested();try{string name=route==""?"GitHub 直连":new Uri(route).Host;lock(gate){state["route"]=name;state["received"]=0;state["total"]=size;}Changed("downloading","正在从 "+name+" 下载；失败将自动换线。");var timer=Stopwatch.StartNew();long lastTime=-500;UpdateProtocol.Download(route+UpdateProtocol.Text(a,"url"),part,size,token,n=>{if(timer.ElapsedMilliseconds-lastTime<250&&n!=size)return;lastTime=timer.ElapsedMilliseconds;lock(gate){state["received"]=n;state["speed"]=timer.ElapsedMilliseconds>0?n*1000/timer.ElapsedMilliseconds:0;}emit(Snapshot());});UpdateProtocol.VerifyFile(part,a);if(File.Exists(Package))File.Delete(Package);File.Move(part,Package);File.WriteAllText(Path.Combine(dir,"manifest.json"),raw);Changed("ready","下载完成，发布签名与文件校验均已通过。");return;}catch(Exception e){last=e;if(File.Exists(part))File.Delete(part);}}throw new Exception("下载线路均未成功，请重试或更换镜像。"+(last==null?"":" "+last.Message));}catch(Exception e){if(File.Exists(part))try{File.Delete(part);}catch{}Changed(token.IsCancellationRequested?"available":"error",token.IsCancellationRequested?"已取消下载，可重新下载。":e.Message);}finally{End();}});}
 void Install(){lock(gate){if(busy||Convert.ToString(state["phase"])!="ready")throw new Exception("请先完成下载并校验");busy=true;}try{var p=UpdateProtocol.Verify(envelope,"windows");if(UpdateProtocol.VersionOf(UpdateProtocol.Text(p,"version"))<=UpdateProtocol.VersionOf(UpdateProtocol.Current))throw new Exception("不允许安装旧版");UpdateProtocol.VerifyFile(Package,UpdateProtocol.Object(p,"windows"));string helper=Path.Combine(dir,"StarcaseUpdater.exe");File.Copy(Path.Combine(Program.BaseDir,"StarcaseUpdater.exe"),helper,true);string job=Path.Combine(dir,"install-job.json");File.WriteAllText(job,UpdateProtocol.Serializer().Serialize(new{target=Path.GetFullPath(Program.BaseDir),pid=Process.GetCurrentProcess().Id,package=Package,manifest=envelope}));Process.Start(new ProcessStartInfo(helper,"\""+job+"\""){UseShellExecute=false,WorkingDirectory=dir});Changed("installing","正在保存并关闭星匣，更新后会自动重新打开。");System.Windows.Forms.Application.Exit();}catch{lock(gate){busy=false;}throw;}}
}
